// Running golang-migrate as a library against embedded files.
import (
	"github.com/golang-migrate/migrate/v4"
	_ "github.com/golang-migrate/migrate/v4/database/postgres"
	_ "github.com/golang-migrate/migrate/v4/source/file"
)

func migrateUp(dbURL string) error {
	m, err := migrate.New("file://migrations", dbURL)
	if err != nil {
		return err
	}
	if err := m.Up(); err != nil && err != migrate.ErrNoChange {
		return err // ErrNoChange just means already up-to-date
	}
	return nil
}

// A goose Go migration: register up/down functions.
package migrations

import (
	"database/sql"
	"github.com/pressly/goose/v3"
)

func init() {
	goose.AddMigration(upBackfillSlugs, downBackfillSlugs)
}

func upBackfillSlugs(tx *sql.Tx) error {
	_, err := tx.Exec(`UPDATE articles SET slug = lower(replace(title, ' ', '-'))`)
	return err
}

func downBackfillSlugs(tx *sql.Tx) error {
	_, err := tx.Exec(`UPDATE articles SET slug = NULL`)
	return err
}

// Embed migrations into the binary and run them via iofs.
package main

import (
	"embed"
	"github.com/golang-migrate/migrate/v4"
	"github.com/golang-migrate/migrate/v4/source/iofs"
	_ "github.com/golang-migrate/migrate/v4/database/postgres"
)

//go:embed migrations/*.sql
var migrationsFS embed.FS

func migrate_(dbURL string) error {
	d, err := iofs.New(migrationsFS, "migrations") // read from embedded FS
	if err != nil {
		return err
	}
	m, err := migrate.NewWithSourceInstance("iofs", d, dbURL)
	if err != nil {
		return err
	}
	return m.Up()
}

// Expand/contract to rename a column with zero downtime.
// Step 1 (migration): add new column, keep old one.
//   ALTER TABLE users ADD COLUMN full_name TEXT;
// Step 2 (code): write BOTH columns, read new-then-old.
// Step 3 (backfill migration): UPDATE users SET full_name = name.
// Step 4 (code): read/write only full_name.
// Step 5 (migration): ALTER TABLE users DROP COLUMN name;
// Each step is safe with the previous version still running.

