	"github.com/golang-migrate/migrate/v4"
	_ "github.com/golang-migrate/migrate/v4/database/postgres"
	"github.com/golang-migrate/migrate/v4/source/iofs"
)

// Migrate applies all embedded migrations; safe to re-run.
func Migrate(fs embed.FS, dbURL string) error {
	src, err := iofs.New(fs, "migrations") // read from the embedded FS
	if err != nil {
		return err
	}
	m, err := migrate.NewWithSourceInstance("iofs", src, dbURL)
	if err != nil {
		return err
	}
	defer m.Close() // release the DB advisory lock
	if err := m.Up(); err != nil && !errors.Is(err, migrate.ErrNoChange) {
		return err // ErrNoChange means already up to date
	}
	return nil
}

package migrations

import (
	"database/sql"
	"strings"

	"github.com/pressly/goose/v3"
)

func init() {
	goose.AddMigration(upBackfillSlugs, downBackfillSlugs)
}

func slugify(s string) string {
	return strings.ToLower(strings.ReplaceAll(strings.TrimSpace(s), " ", "-"))
}

func upBackfillSlugs(tx *sql.Tx) error {
	rows, err := tx.Query(`SELECT id, title FROM articles WHERE slug IS NULL`)
	if err != nil {
		return err
	}
	type rec struct {
		id    int64
		title string
	}
	var recs []rec
	for rows.Next() {
		var r rec
		if err := rows.Scan(&r.id, &r.title); err != nil {
			rows.Close()
			return err
		}
		recs = append(recs, r)
	}
	if err := rows.Err(); err != nil {
		rows.Close()
		return err
	}
	rows.Close() // free the connection before issuing updates
	for _, r := range recs {
		if _, err := tx.Exec(`UPDATE articles SET slug = $1 WHERE id = $2`, slugify(r.title), r.id); err != nil {
			return err
		}
	}
	return nil
}

func downBackfillSlugs(tx *sql.Tx) error {
	_, err := tx.Exec(`UPDATE articles SET slug = NULL`)
	return err
}
